CREATE TYPE "AnalyticsEventType" AS ENUM ('PORTFOLIO_VIEW','PROJECT_CLICK','PAGE_VIEW');
CREATE TABLE "VisitorSession" ("id" TEXT NOT NULL,"portfolioId" TEXT NOT NULL,"anonymousId" TEXT NOT NULL,"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"visitCount" INTEGER NOT NULL DEFAULT 1,"country" TEXT NOT NULL DEFAULT 'Unknown',"state" TEXT NOT NULL DEFAULT 'Unknown',"city" TEXT NOT NULL DEFAULT 'Unknown',"device" TEXT NOT NULL DEFAULT 'Other',"browser" TEXT NOT NULL DEFAULT 'Other',CONSTRAINT "VisitorSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AnalyticsEvent" ("id" TEXT NOT NULL,"portfolioId" TEXT NOT NULL,"projectId" TEXT,"sessionId" TEXT NOT NULL,"type" "AnalyticsEventType" NOT NULL,"page" TEXT NOT NULL,"referrer" TEXT NOT NULL DEFAULT 'Direct',"device" TEXT NOT NULL DEFAULT 'Other',"browser" TEXT NOT NULL DEFAULT 'Other',"country" TEXT NOT NULL DEFAULT 'Unknown',"state" TEXT NOT NULL DEFAULT 'Unknown',"city" TEXT NOT NULL DEFAULT 'Unknown',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AnalyticsEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VisitorSession_portfolioId_anonymousId_key" ON "VisitorSession"("portfolioId","anonymousId"); CREATE INDEX "VisitorSession_portfolioId_lastSeenAt_idx" ON "VisitorSession"("portfolioId","lastSeenAt"); CREATE INDEX "VisitorSession_portfolioId_firstSeenAt_idx" ON "VisitorSession"("portfolioId","firstSeenAt"); CREATE INDEX "AnalyticsEvent_portfolioId_createdAt_idx" ON "AnalyticsEvent"("portfolioId","createdAt"); CREATE INDEX "AnalyticsEvent_portfolioId_type_createdAt_idx" ON "AnalyticsEvent"("portfolioId","type","createdAt"); CREATE INDEX "AnalyticsEvent_projectId_createdAt_idx" ON "AnalyticsEvent"("projectId","createdAt"); CREATE INDEX "AnalyticsEvent_sessionId_createdAt_idx" ON "AnalyticsEvent"("sessionId","createdAt");
ALTER TABLE "VisitorSession" ADD CONSTRAINT "VisitorSession_portfolioId_fkey" FOREIGN KEY ("portfolioId") REFERENCES "Portfolio"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AnalyticsEvent" ADD CONSTRAINT "AnalyticsEvent_portfolioId_fkey" FOREIGN KEY ("portfolioId") REFERENCES "Portfolio"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AnalyticsEvent" ADD CONSTRAINT "AnalyticsEvent_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AnalyticsEvent" ADD CONSTRAINT "AnalyticsEvent_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "VisitorSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
